export const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function materialKey(abbr){if(/PPE|PPO/.test(abbr))return 'PPE';if(/TPEE|TPC-ET/.test(abbr))return 'TPEE';if(/PEBA|TPAE/.test(abbr))return 'PEBA';return abbr}
const families=[{keys:['PET','PTT','PBT','TPEE'],label:'聚酯与聚酯硬段关联'},{keys:['PA6','PA66','PA11','PA12','PEBA','TPEE','TPU'],label:'聚酰胺与嵌段弹性体关联'},{keys:['PPE','PS','PA6','PA66'],label:'聚苯醚合金的常见关联材料'}];
export function relatedMaterials(m,all){const key=materialKey(m.fields['英文缩写']);const groups=families.filter(g=>g.keys.includes(key));const seen=new Set([key]);const results=[];for(const g of groups)for(const k of g.keys){if(seen.has(k))continue;const found=all.find(x=>x.id!==m.id&&materialKey(x.fields['英文缩写'])===k);if(found){seen.add(k);results.push({material:found,label:g.label})}}if(results.length)return results.slice(0,5);return all.filter(x=>x.id!==m.id&&x.category===m.category&&materialKey(x.fields['英文缩写'])!==key).slice(0,4).map(x=>({material:x,label:'同分类资料'}))}
export function relatedMarkup(m,all){const list=relatedMaterials(m,all);if(!list.length)return '';const e=escapeHtml;return `<section class="related-materials"><h3>关联材料</h3><p>按结构、嵌段或常见共混关系延伸阅读；关联不表示性能相同或能够直接替代。</p><div>${list.map(({material:x,label})=>`<button class="related-material" data-related="${e(x.id)}"><strong>${e(x.fields['英文缩写'])}</strong><span>${e(x.fields['材料名称'])}</span><small>${e(label)} ↗</small></button>`).join('')}</div></section>`}
const normalize=v=>String(v??'').replace(/\s+/g,' ').trim();
export function comparisonRows(materials){const fields=[...new Set(materials.flatMap(m=>Object.keys(m.fields)))].filter(k=>!['材料名称','英文缩写','参考来源与核验范围'].includes(k));return fields.map(key=>{const values=materials.map(m=>m.fields[key]??'');const normalized=values.map(normalize);return {key,values,same:new Set(normalized).size===1,shared:normalized.map(v=>normalized.filter(x=>x===v).length>1)}})}
export const termAliases=[['玻璃化转变','Tg 玻璃化转变'],['Tg','Tg 玻璃化转变'],['Tm','Tm 熔点'],['HDT','HDT与长期耐温'],['结晶度','结晶性与交联'],['结晶性','结晶性与交联'],['交联','结晶性与交联'],['醇解','醇解、水解、氨解'],['水解','吸水与水解'],['氨解','醇解、水解、氨解'],['BHET','BHET/BHPT/BHBT'],['BHPT','BHET/BHPT/BHBT'],['BHBT','BHET/BHPT/BHBT'],['TPA','TPA/DMT/EG/PDO/BDO'],['DMT','TPA/DMT/EG/PDO/BDO'],['PTMG','PTMG/PTMEG/PEG'],['PTMEG','PTMG/PTMEG/PEG'],['PEG','PTMG/PTMEG/PEG'],['软段','软段与硬段'],['硬段','软段与硬段'],['单体收率','单体收率、纯度、选择性'],['选择性','单体收率、纯度、选择性'],['金属浸出','催化剂回收与浸出']];
export function termMatches(text,terms){const available=termAliases.map(([alias,title])=>({alias,index:terms.findIndex(x=>x['术语/阅读规则']===title)})).filter(x=>x.index>=0).sort((a,b)=>b.alias.length-a.alias.length);if(!available.length)return[];const escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const regex=new RegExp(available.map(x=>/^[A-Za-z]+$/.test(x.alias)?`(?<![A-Za-z0-9_])${escape(x.alias)}(?![A-Za-z0-9_])`:escape(x.alias)).join('|'),'g');return [...String(text).matchAll(regex)].map(m=>({start:m.index,text:m[0],index:available.find(x=>x.alias===m[0]).index}))}
export function annotateTerms(root,terms){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(n.parentElement.closest('p,dd')&&!n.parentElement.closest('button,a,.formula,.source-text,svg,.structure-figure,.related-materials'))nodes.push(n)}for(const n of nodes){const matches=termMatches(n.textContent,terms);if(!matches.length)continue;const fragment=document.createDocumentFragment();let at=0;for(const m of matches){fragment.append(document.createTextNode(n.textContent.slice(at,m.start)));const b=document.createElement('button');b.type='button';b.className='inline-term';b.dataset.termHelp=String(m.index);b.textContent=m.text;b.setAttribute('aria-label',`解释术语：${m.text}`);b.setAttribute('aria-haspopup','dialog');fragment.append(b);at=m.start+m.text.length}fragment.append(document.createTextNode(n.textContent.slice(at)));n.replaceWith(fragment)}}
